components.source:
Button { model.startScan() } label: { Label("Scan storage", systemImage: "magnifyingglass") }
.buttonStyle(.borderedProminent).controlSize(.large)
.disabled(model.enabledCategories.isEmpty)

TextField("Filter by name or path", text: $model.query).textFieldStyle(.plain)
// The containing HStack applies:
.padding(9).background(Palette.canvas, in: RoundedRectangle(cornerRadius: 6))

Button { selection = tool } label: {
    HStack {
        Label(tool.title, systemImage: tool.symbol)
        Spacer(minLength: 4)
        // A mini ProgressView appears while this tool is busy.
    }
    .font(.system(size: 14, weight: selection == tool ? .semibold : .regular))
    .foregroundStyle(selection == tool ? Palette.accent : .primary)
    .padding(.horizontal, 13).padding(.vertical, 12)
    .contentShape(Rectangle())
    .background(selection == tool ? Palette.accent.opacity(0.10) : .clear, in: RoundedRectangle(cornerRadius: 8))
}
.buttonStyle(.plain)
.accessibilityAddTraits(selection == tool ? [.isSelected] : [])

components.meterSource:
RoundedRectangle(cornerRadius: 5).fill(Palette.accent.opacity(0.10))
RoundedRectangle(cornerRadius: 5).fill(Palette.accent).frame(width: max(0, geometry.size.width * disk.fraction))
// GeometryReader has .frame(height: 13)

components.source:
HStack(spacing: 12) {
    breadcrumbs
    Menu {
        Toggle("Include hidden items", isOn: $model.includeHidden)
            .help("Rescan the current folder with or without hidden items.")
    } label: { Image(systemName: "slider.horizontal.3") }
    .fixedSize().menuStyle(.borderlessButton).menuIndicator(.hidden)
    .help("Scan options").accessibilityLabel("Scan options")
    Button("Choose folder…") { model.chooseFolder() }
        .disabled(model.isScanning || model.isDemo)
}

Button { model.goBack() } label: { Image(systemName: "chevron.left") }
.disabled(model.breadcrumbs.count < 2)
.help("Go to the parent folder and scan it")
.accessibilityLabel("Go to the parent folder")
.keyboardShortcut("[", modifiers: .command)
// Horizontally scrolling native link buttons scan ancestors.
// Current crumb is non-interactive 13pt semibold text; ancestors use 12pt native links.
// ScrollViewReader scrolls to the current crumb on appearance and navigation changes.
// A separate current-folder Finder reveal remains available during scanning.

VStack(alignment: .leading, spacing: 18) {
    // Item-specific question, full path, allocated size, and restoration sentence.
    // Folders also state that all contents, including hidden items, move with them.
    HStack {
        Spacer()
        Button("Cancel", role: .cancel, action: onCancel)
            .keyboardShortcut(.defaultAction)
        Button("Move to Trash", role: .destructive, action: onConfirm)
            .buttonStyle(.borderedProminent).disabled(isDemo)
    }
}
.padding(26).frame(width: 470)
.onExitCommand(perform: onCancel)

applicationList.frame(width: 260)
// HStack uses spacing: 24 and a native Divider; outer horizontal inset is 36pt.
// Row: AppIcon 32×32pt, 13pt medium name, 11pt version, padding 9pt.
.background(isSelected ? Palette.accent.opacity(0.12) : .clear, in: RoundedRectangle(cornerRadius: 8))

VStack(alignment: .leading, spacing: 18) {
    // App-specific question, removal consequence, scrolling item paths and sizes.
    // ScrollView has frame(maxHeight: 220).
    // Cancel uses the default Return action; Move to Trash is destructive and disabled in demo.
}
.padding(26).frame(width: 560)
.onExitCommand(perform: onCancel)
